var record3 = (store2, orgId, by, action, detail) => store2.audit({ id: newId(), orgId, at: nowIso(), actor: by, action, taskId: null, detail });
var label3 = (c) => c.company || c.name;
async function customerOf(store2, orgId, contactId4) {
  const c = (await loadCrm(store2, orgId)).contacts.find((x) => x.id === String(contactId4 ?? "").trim());
  if (!c) throw new Error(`No deal with id "${String(contactId4 ?? "")}" in the CRM. Use read_crm to find the right id.`);
  return c;
}
async function saveOnboarding(store2, orgId, contactId4, input, by) {
  const c = await customerOf(store2, orgId, contactId4);
  if (c.stage !== "won") throw new Error(`${label3(c)} is not a won customer yet (stage ${c.stage}). Onboarding starts after the win.`);
  const plan = { id: newId(), ...cleanOnboarding(input) };
  await record3(store2, orgId, by, "crm.onboarding", { contactId: c.id, onboarding: plan, summary: `${label3(c)}: onboarding plan saved` });
  return `Saved an onboarding plan with ${plan.steps.length} steps${plan.welcome ? " and a welcome email draft" : ""} on ${label3(c)}. Nothing was sent.`;
}
async function saveAccountReview(store2, orgId, contactId4, input, by) {
  const c = await customerOf(store2, orgId, contactId4);
  if (c.stage !== "won") throw new Error(`${label3(c)} is not a customer yet (stage ${c.stage}). Account reviews are for won deals.`);
  const review = { id: newId(), ...cleanReview(input) };
  await record3(store2, orgId, by, "crm.account", { contactId: c.id, review, summary: `${label3(c)}: account review, health ${review.health}` });
  return `Saved the account review on ${label3(c)}: health ${review.health} (${review.band.replace("_", " ")}). Nothing was sent.`;
}
function findGoal(a) {
  return a.icp ? prospectGoal(a.icp, "", FIND_COUNT) : "";
}
function onboardingGoal(id) {
  return `Plan the onboarding for this new customer (deal id ${id}). Read the deal with read_crm view "deal" (contactId ${id}) and the ICPs (view "icps") for the voice. Then call save_onboarding once with: 5 to 8 steps over the first 30 days, each with a day number, a short title and who owns it ("you" for the owner, "customer", or "agent" for work an agent can draft); a welcome email from the owner in the first person (subject and text: thank them, confirm what they bought as the record states it, propose the kickoff and say what happens in week one); and a 30-minute kickoff agenda. Write short and warm. Use [DATE], [PRICE] or [First name] where the record does not say; promise nothing the record does not show. These are drafts; nothing is sent.`;
}
function accountReviewGoal(id) {
  return `Review the health of this customer (deal id ${id}). Read the deal with read_crm view "deal" (contactId ${id}): its history, notes, onboarding progress and any earlier review. Then call save_account_review once with: a health score from 0 to 100 and the reasons (onboarding progress, how recently and how warmly they replied, results or problems in the notes, open issues); the risks; a short check-in message from the owner in the first person that asks one useful question; the renewal date only if the record states one, and a renewal plan; up to three upsell or cross-sell ideas tied to what they bought and their pains; and, only when health is 70 or more, a short referral ask. Base every point on the record and say what is unknown. These are drafts; nothing is sent.`;
}
function replyGoal(c) {
  if (!c.email) return "";
  return `A new enquiry has not heard from us yet. Write one short first reply and queue it with send_message (channel "email", to ${c.email}): thank them by first name, answer what they asked only from known facts, and offer one clear next step such as a call, a visit or a booking link from memory. Under 90 words, warm and plain. Do not ask for more personal details than the next step needs. The owner approves it before it goes.
- ${c.name}${c.company ? ` (${c.company})` : ""}, came from ${c.sourceDetail || c.source}${c.notes ? `, wrote: ${c.notes.slice(0, 400)}` : ""}`;
}
