      id: newId(),
      orgId: task.orgId,
      taskId: task.id,
      kind: gate === "await_approval" ? "approve" : "draft",
      taskType: tt.key,
      summary: tool.summarize(use.input),
      proposed: use.input,
      status: "pending",
      edited: null,
      reason: null,
      decidedBy: null,
      createdAt: nowIso(),
      decidedAt: null
