var MAX_TOKENS = { router: 1024, worker: 8192, planner: 8192 };
async function runTask(deps, taskId) {
  let task = await deps.store.getTask(taskId);
  if (!task) throw new Error(`Task ${taskId} not found`);
  const agent = getAgent(task.agentId);
  if (!agent || !agent.usesModel) throw new Error(`Agent ${task.agentId} cannot run tasks`);
  const types = new Map((await deps.store.getTaskTypes(task.orgId)).map((t) => [t.key, t]));
  const tools = [...toolsFor(agent).map((t) => t.spec), ...agent.tools.includes("web_search") ? [WEB_SEARCH_TOOL] : []];
  const maxTurns = deps.maxTurns ?? agent.maxTurns ?? 8;
  const queued = [];
  task = await deps.store.updateTask(task.id, { status: "running" });
  for (let turn = 0; turn < maxTurns; turn++) {
    const resp = await deps.model.complete({
      tier: agent.modelTier,
      system: await systemPrompt(deps.store, agent, task, deps.journey),
      messages: task.transcript,
      tools,
      maxTokens: MAX_TOKENS[agent.modelTier]
    });
    await recordUsage(deps.store, task.orgId, task.id, agent.id, resp);
    const transcript = [...task.transcript, { role: "assistant", content: resp.content }];
    const uses = resp.content.filter((b) => b.type === "tool_use");
    if (uses.length === 0) {
      if (resp.stopReason === "pause_turn") {
        task = await deps.store.updateTask(task.id, { transcript });
        continue;
      }
      if (resp.stopReason === "max_tokens") {
        const nudge = { role: "user", content: "Your reply was cut off at the length limit. Finish with a shorter summary." };
        task = await deps.store.updateTask(task.id, { transcript: [...transcript, nudge] });
        continue;
      }
      task = await deps.store.updateTask(task.id, { transcript, status: "done", output: textOf(resp.content), pending: null });
      await audit(deps.store, task.orgId, agent.id, "task.done", task.id, { output: task.output, queued: queued.length });
      return { task, approvals: queued, approval: queued[0] };
    }
    task = await deps.store.updateTask(task.id, { transcript });
    const step = await processToolUses(deps, task, agent, types, uses, []);
    queued.push(...step.approvals);
    task = await deps.store.updateTask(task.id, { transcript: [...transcript, { role: "user", content: step.results }] });
  }
  task = await deps.store.updateTask(task.id, { status: "failed", output: `Stopped after ${maxTurns} turns without finishing.` });
  await audit(deps.store, task.orgId, agent.id, "task.failed", task.id, { reason: "turn limit" });
  return { task, approvals: queued, approval: queued[0] };
}

// core/autopilot.ts
async function runAutopilot(deps, orgId, max = 3, force = false) {
  const store2 = deps.store;
  const crm = await loadCrm(store2, orgId);
  if (!force && !crm.flowOrg.autopilot?.on) return { ran: [], skipped: "Autopilot is off" };
  const todo = crm.nextActions.filter((a) => AUTO_RULES.includes(a.rule) && a.agentId && a.contactId).slice(0, Math.max(0, Math.min(5, max)));
  const ran = [];
  for (const a of todo) {
    const agent = getAgent(a.agentId);
    const goal = autoGoal(a, crm.contacts.find((c) => c.id === a.contactId));
    if (!agent || !goal) continue;
    try {
      const task = await createTask(store2, orgId, agent.id, goal);
      const run = await runTask(deps, task.id);
      await logAgentRun(store2, orgId, a.contactId, agent.name, run.task.status, run.task.output, run.approvals?.length ?? 0).catch(() => false);
      ran.push({ key: a.key, agentId: agent.id, status: run.task.status });
    } catch (e) {
      ran.push({ key: a.key, agentId: agent.id, status: `failed: ${e instanceof Error ? e.message.slice(0, 120) : "error"}` });
    }
  }
  if (ran.length) await store2.audit({ id: newId(), orgId, at: nowIso(), actor: "Sales autopilot", action: "autopilot.ran", taskId: null, detail: { ran, summary: `Sales autopilot prepared ${ran.length} draft${ran.length === 1 ? "" : "s"}` } });
  return { ran, skipped: todo.length ? "" : "Nothing for the autopilot to prepare" };
}
async function runAutofind(deps, orgId, force = false) {
  const store2 = deps.store;
  const crm = await loadCrm(store2, orgId);
  if (!force && !crm.flowOrg.autofind?.on) return { status: "off" };
  const a = crm.nextActions.find((x) => x.rule === "find");
  const goal = a ? findGoal(a) : "";
  const agent = getAgent("lead-finder");
  if (!a || !goal || !agent) return { status: "not due" };
  let status;
  try {
    const task = await createTask(store2, orgId, agent.id, goal);
    status = (await runTask(deps, task.id)).task.status;
  } catch (e) {
    status = `failed: ${e instanceof Error ? e.message.slice(0, 120) : "error"}`;
  }
  await store2.audit({ id: newId(), orgId, at: nowIso(), actor: "Weekly prospect search", action: "autofind.ran", taskId: null, detail: { icp: a.icp?.name ?? "", status, summary: `Weekly prospect search for ${a.icp?.name ?? "your ICP"}: ${status}` } });
  return { status };
}

